import{_ as i,a0 as o,w as l,s as d,ao as r,I as p,x as t,a1 as a,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const $=JSON.parse('{"title":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 的 ‘next’ 命令 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 6 - How to Use ‘next’ Command with Awk in Linux","title":"awk 系列：如何使用 awk 的 ‘next’ 命令","tag":"awk","desc":""},"relativePath":"awk/Part 6 - How to Use ‘next’ Command with Awk in Linux.md","filePath":"[post].md"}'),k={name:"awk/Part 6 - How to Use ‘next’ Command with Awk in Linux.md"};function u(c,n,w,m,x,g){const s=o("Link");return l(),d("div",null,[n[13]||(n[13]=r(`<h1 id="awk-系列-如何使用-awk-的-next-命令" tabindex="-1">awk 系列：如何使用 awk 的 ‘next’ 命令 <a class="header-anchor" href="#awk-系列-如何使用-awk-的-next-命令" aria-label="Permalink to “awk 系列：如何使用 awk 的 ‘next’ 命令”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/06/Use-next-Command-with-Awk-in-Linux.png" alt=""></p><p>在 awk 系列的第六节，我们来看一下<code>next</code>命令 ，它告诉 awk 跳过你所提供的所有剩下的模式和表达式，直接处理下一个输入行。</p><p><code>next</code> 命令帮助你阻止运行命令执行过程中多余的步骤。</p><p>要明白它是如何工作的, 让我们来分析一下 food_list.txt 它看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Food List Items</span></span>
<span class="line"><span>No      Item_Name               Price           Quantity</span></span>
<span class="line"><span>1       Mangoes                 $3.45              5</span></span>
<span class="line"><span>2       Apples                  $2.45              25</span></span>
<span class="line"><span>3       Pineapples              $4.45              55</span></span>
<span class="line"><span>4       Tomatoes                $3.45              25</span></span>
<span class="line"><span>5       Onions                  $1.45              15</span></span>
<span class="line"><span>6       Bananas                 $3.45              30</span></span></code></pre></div><p>运行下面的命令，它将在每个食物数量小于或者等于 20 的行后面标一个星号:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$4 &lt;= 20 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;*&quot; ; } $4 &gt; 20 { print $0 ;} &#39; food_list.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	Item_Name		Price		Quantity</span></span>
<span class="line"><span>1	  Mangoes			$3.45		   5	*</span></span>
<span class="line"><span>2	  Apples			$2.45      25</span></span>
<span class="line"><span>3	  Pineapples	$4.45      55</span></span>
<span class="line"><span>4	  Tomatoes		$3.45      25 </span></span>
<span class="line"><span>5	  Onions			$1.45      15	*</span></span>
<span class="line"><span>6	  Bananas	    $3.45      30</span></span></code></pre></div><p>上面的命令实际运行如下:</p><ul><li>首先，它用<code>$4 &lt;= 20</code>表达式检查每个输入行的第四列（数量（Quantity））是否小于或者等于 20，如果满足条件，它将在末尾打一个星号 <code>(*)</code>。</li><li>接着，它用<code>$4 &gt; 20</code>表达式检查每个输入行的第四列是否大于20，如果满足条件，显示出来。</li></ul><p>但是这里有一个问题, 当第一个表达式用<code>{ printf &quot;%s\\t%s\\n&quot;, $0,&quot;**&quot; ; }</code>命令进行标注的时候在同样的步骤第二个表达式也进行了判断这样就浪费了时间.</p><p>因此当我们已经用第一个表达式打印标志行的时候就不再需要用第二个表达式<code>$4 &gt; 20</code>再次打印。</p><p>要处理这个问题, 我们需要用到<code>next</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$4 &lt;= 20 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;*&quot; ; next; } $4 &gt; 20 { print $0 ;} &#39; food_list.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	Item_Name		Price		           Quantity</span></span>
<span class="line"><span>1	  Mangoes			$3.45		           5	*</span></span>
<span class="line"><span>2	  Apples			$2.45              25</span></span>
<span class="line"><span>3	  Pineapples	$4.45              55</span></span>
<span class="line"><span>4	  Tomatoes		$3.45              25 </span></span>
<span class="line"><span>5	  Onions			$1.45              15	*</span></span>
<span class="line"><span>6	  Bananas	    $3.45              30</span></span></code></pre></div><p>当输入行用<code>$4 &lt;= 20</code> <code>{ printf &quot;%s\\t%s\\n&quot;, $0,&quot;*&quot; ; next ; }</code>命令打印以后，<code>next</code>命令将跳过第二个<code>$4 &gt; 20</code> <code>{ print $0 ;}</code>表达式，继续判断下一个输入行，而不是浪费时间继续判断一下是不是当前输入行还大于 20。</p><p><code>next</code>命令在编写高效的命令脚本时候是非常重要的，它可以提高脚本速度。本系列的下一部分我们将来学习如何使用 awk 来处理标准输入（STDIN）。</p><p>希望这篇文章对你有帮助，你可以给我们留言。</p><hr>`,18)),p("p",null,[n[1]||(n[1]=t("via: ",-1)),a(s,{href:"http://www.tecmint.com/use-next-command-with-awk-in-linux/"},{default:e(()=>[...n[0]||(n[0]=[t("http://www.tecmint.com/use-next-command-with-awk-in-linux/",-1)])]),_:1})]),p("p",null,[n[5]||(n[5]=t("作者：",-1)),a(s,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...n[2]||(n[2]=[t("Aaron Kili",-1)])]),_:1}),n[6]||(n[6]=t(" 译者：",-1)),a(s,{href:"https://github.com/kokialoves"},{default:e(()=>[...n[3]||(n[3]=[t("kokialoves",-1)])]),_:1}),n[7]||(n[7]=t(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:e(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),p("p",null,[n[10]||(n[10]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:e(()=>[...n[9]||(n[9]=[t("Linux中国",-1)])]),_:1}),n[12]||(n[12]=t(" 荣誉推出",-1))])])}const C=i(k,[["render",u]]);export{$ as __pageData,C as default};
